{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C64"],
      "claim": "Brexpiprazole, the closest structural analogue sharing the quinolinone-O-butyl-N-arylpiperazine core, has an absolute oral bioavailability of 95% in humans, strongly supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Ziprasidone, another arylpiperazine antipsychotic with similar physicochemical features, has an absolute oral bioavailability of about 59% in healthy men, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Urapidil, an N-arylpiperazine drug, shows an absolute oral bioavailability of 78% from an oral solution, supporting high oral absorption for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Trazodone, an arylpiperazine antidepressant, has systemic availability of 0.91 after oral dosing in elderly men, supporting high oral bioavailability for related piperazine-containing drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Prochlorperazine, a more distantly related phenothiazine piperazine, has low absolute oral bioavailability of about 12.5%, providing a contradictory example but with substantially lower structural transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is aripiprazole-like: a quinolinone O-butyl-linked N-arylpiperazine. The closest analogue brexpiprazole has 95% absolute oral bioavailability, and multiple related arylpiperazine drugs have F values of 50-90%, all above the 20% threshold. The low-bioavailability example prochlorperazine is structurally more distant and does not override the strong supportive evidence. Therefore, the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule is included in the provided evidence.",
    "The effect of food on absorption is not directly assessed for the query; some analogues show food-dependent bioavailability.",
    "High lipophilicity and solubility concerns from the physicochemical prior are not directly tested in the experimental evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

